/**
 * @brief get adc reference voltage
 *
 * @param[in] port_num

 *
 * @return adc reference voltage(bat: mv)
 */
uint32_t tkl_adc_ref_voltage_get(TUYA_ADC_NUM_E port_num)
{
    // --- BEGIN: user implements ---
    // Standard TI LaunchPads use 3.3V (3300mV) as VRef.
    // return 3300;
    // 2. DYNAMIC VREF DISCOVERY
    // Instead of hardcoding 3300, we ask the driver:
    // "If I read the maximum possible raw value (4095), what voltage is that?"
    
    if (is_valid_adc(port_num) && g_adc_handles[port_num] != NULL) {
        // Calculate VRef based on current driver configuration (3.3V or 1.4V internal)
        uint32_t vref_microvolts = ADC_convertToMicroVolts(g_adc_handles[port_num], TI_ADC_MAX_RAW_VALUE);
        return (vref_microvolts / 1000); // Convert uV to mV
    }

    // Fallback if driver is not open yet (Standard Logic Level)
    return 3300;
    // --- END: user implements ---
}

